def install(confirm=False):
    target=Path.home()/'.config/look/completions/_lk'
    value={'path':str(target),'applied':False,'note':'Updates the LOOK zsh completion; open a new shell afterward.'}
    if confirm is not True:return value
    if target.is_symlink():raise ValueError('Completion path is a symlink; update it with the installer')
    target.parent.mkdir(parents=True,exist_ok=True)
    if target.exists():
        prior=target.read_bytes()
        if prior==SCRIPT.encode():return dict(value,applied=True,unchanged=True)
        backup=target.with_name('_lk.before-'+hashlib.sha256(prior).hexdigest()[:12])
        if not backup.exists():backup.write_bytes(prior)
    temporary=target.with_name('.lk-'+uuid.uuid4().hex)
    try:
        temporary.write_text(SCRIPT);os.replace(temporary,target)
    finally:temporary.unlink(missing_ok=True)
    return dict(value,applied=True)
